class Solution {public String[]solve(int n,int[][]edges){if(n==0)return new String[0];long inf=Long.MAX_VALUE/4;long[]d=new long[n];Arrays.fill(d,inf);d[0]=0;for(int round=0;round<n-1;round++){boolean changed=false;for(int[]e:edges)if(d[e[0]]!=inf&&d[e[0]]+e[2]<d[e[1]]){d[e[1]]=d[e[0]]+e[2];changed=true;}if(!changed)break;}ArrayList<ArrayList<Integer>>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());boolean[]bad=new boolean[n];ArrayList<Integer>q=new ArrayList<>();for(int[]e:edges){a.get(e[0]).add(e[1]);if(d[e[0]]!=inf&&d[e[0]]+e[2]<d[e[1]]&&!bad[e[1]]){bad[e[1]]=true;q.add(e[1]);}}for(int i=0;i<q.size();i++)for(int v:a.get(q.get(i)))if(!bad[v]){bad[v]=true;q.add(v);}String[]out=new String[n];for(int i=0;i<n;i++)out[i]=bad[i]?"UNBOUNDED":d[i]==inf?"UNREACHABLE":Long.toString(d[i]);return out;}}